sites.sync:
function (doc, oldDoc, meta) {
  // Written only by the backend (Couchbase SDK writes, imported by SG).
  // Phones pull these; any attempt to push one is rejected.
  requireAdmin();
  if (doc._deleted) { if (oldDoc && oldDoc.channels) { channel(oldDoc.channels); } return; }
  channel(doc.channels);
}

