work_orders.sync:
function (doc, oldDoc, meta) {
  // Offline-first work orders and field actions. A tech's phone may CREATE one, as itself,
  // as 'pending'. Only the backend (admin / import) may advance its status.
  if (doc._deleted) { requireAdmin(); if (oldDoc) { channel("tech:" + oldDoc.tech_id); } return; }
  if (!doc.tech_id) { throw({forbidden: "tech_id is required"}); }
  if (oldDoc == null || oldDoc._deleted) {
    requireUser(doc.tech_id);
    if (doc.type !== "request") { throw({forbidden: "type must be 'request'"}); }
    if (doc.status !== "pending") { throw({forbidden: "new work orders must be 'pending'"}); }
    if (doc._id.indexOf("wo::" + doc.tech_id + "::") !== 0) { throw({forbidden: "id must be wo::<tech_id>::<uuid>"}); }
  } else {
    if (oldDoc.tech_id !== doc.tech_id) { throw({forbidden: "tech_id is immutable"}); }
    requireAdmin();
  }
  channel("tech:" + doc.tech_id);
}
